-- =====================================================================
-- MediVault V1 (H2): baseline schema for the "local-file" profile.
-- Mirrors db/migration/mysql/V1__baseline_schema.sql. Column types match
-- what Hibernate 6.6 (H2Dialect) expects, so `ddl-auto=validate` passes:
--   Long @Id IDENTITY   -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--   boolean             -> BOOLEAN
--   Instant             -> TIMESTAMP(6) WITH TIME ZONE
--   LocalDate           -> DATE
--   @Enumerated(STRING) -> native ENUM
--
-- Runs only for the persistent file-backed H2 database (local-file profile).
-- Never edit this file after it has been applied; add V3__... instead.
-- =====================================================================

CREATE TABLE app_users (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY,
    created_at    TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    email         VARCHAR(254)                NOT NULL,
    enabled       BOOLEAN                     NOT NULL,
    full_name     VARCHAR(100)                NOT NULL,
    password_hash VARCHAR(100)                NOT NULL,
    role          ENUM ('ADMIN', 'PATIENT')   NOT NULL,
    updated_at    TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_app_users PRIMARY KEY (id),
    CONSTRAINT uk_app_users_email UNIQUE (email)
);

CREATE TABLE medical_records (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY,
    created_at    TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    notes         VARCHAR(1000)               NULL,
    provider_name VARCHAR(150)                NULL,
    record_date   DATE                        NOT NULL,
    record_type   ENUM ('DISCHARGE_SUMMARY', 'IMAGING', 'LAB_REPORT', 'OTHER', 'PRESCRIPTION', 'VACCINATION') NOT NULL,
    title         VARCHAR(150)                NOT NULL,
    updated_at    TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    owner_id      BIGINT                      NOT NULL,
    CONSTRAINT pk_medical_records PRIMARY KEY (id),
    CONSTRAINT fk_medical_records_owner FOREIGN KEY (owner_id) REFERENCES app_users (id)
);

CREATE INDEX idx_medical_records_owner ON medical_records (owner_id);
